"""Mock data source reading `mock/*.json` generated by `scripts/generate_mock.py`."""

import json
from datetime import date
from pathlib import Path
from typing import Any

from pydantic import BaseModel, Field, TypeAdapter, ValidationError

from studio_pulse import StudioPulseError
from studio_pulse.dates import working_days_back
from studio_pulse.models import Budget, Person, Project, TimeEntry

DEFAULT_MOCK_DIR = Path(__file__).resolve().parents[3] / "mock"


class StoredEntry(BaseModel):
    """A time entry as stored in mock JSON: relative working day instead of a date."""

    id: str
    working_days_ago: int = Field(ge=0)
    person_id: str
    project_id: str
    minutes: int = Field(ge=0)
    billable_minutes: int = Field(ge=0)
    note: str | None = None
    invoiced: bool = False


class MockSource:
    """Fixed fictional agency data. Dates are relative to `today`."""

    def __init__(self, today: date, data_dir: Path = DEFAULT_MOCK_DIR) -> None:
        self._people = _load(data_dir, "people", list[Person])
        self._projects = _load(data_dir, "projects", list[Project])
        self._budgets = _load(data_dir, "budgets", list[Budget])
        stored = _load(data_dir, "time_entries", list[StoredEntry])
        self._entries = [_to_time_entry(entry, today) for entry in stored]

    def people(self) -> list[Person]:
        return list(self._people)

    def projects(self) -> list[Project]:
        return list(self._projects)

    def budgets(self) -> list[Budget]:
        return list(self._budgets)

    def time_entries(self, date_from: date, date_to: date) -> list[TimeEntry]:
        return [entry for entry in self._entries if date_from <= entry.date <= date_to]


def _to_time_entry(entry: StoredEntry, today: date) -> TimeEntry:
    return TimeEntry(
        date=working_days_back(today, entry.working_days_ago),
        **entry.model_dump(exclude={"working_days_ago"}),
    )


def _load[T](data_dir: Path, name: str, model: type[T]) -> T:
    path = data_dir / f"{name}.json"
    try:
        raw: Any = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        raise StudioPulseError(
            f"Mock data file {path} not found. Run: uv run python scripts/generate_mock.py"
        ) from None
    except json.JSONDecodeError as exc:
        raise StudioPulseError(f"Mock data file {path} is not valid JSON: {exc}") from None
    try:
        return TypeAdapter(model).validate_python(raw)
    except ValidationError as exc:
        raise StudioPulseError(f"Mock data file {path} has invalid content: {exc}") from None
